<style>
.sp-dialog{width:min(1100px,calc(100vw - 24px));max-height:90vh;overflow:auto;border:1px solid #e2e8ee;border-radius:12px;padding:22px;color:#16242b;background:#fff;box-shadow:0 24px 80px #10243540}.sp-dialog.small{width:min(580px,calc(100vw - 24px))}.sp-dialog::backdrop{background:#152a466e}.sp-dialog h2{margin:0;font-size:19px}.sp-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.sp-form{display:grid;gap:14px;margin-top:18px}.sp-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.sp-dialog .sc-table{margin:14px 0;min-width:580px}.sp-dialog .sc-table td{padding:10px 12px}.sp-count-input{width:115px;max-width:100%;padding:10px;border:1px solid #cdd8e3;border-radius:6px;color:#16242b;font:inherit;font-size:14px}.sp-count-search{padding:10px;border:1px solid #cdd8e3;border-radius:7px;width:300px;max-width:100%;font:inherit;font-size:13px}.sp-dialog .sc-field input,.sp-dialog .sc-field select,.sp-dialog .sc-field textarea{font-size:13px}.sp-variance.negative{color:#b42318}.sp-variance.positive{color:#166534}.sp-variance{font-weight:700;font-variant-numeric:tabular-nums}.sp-dialog [hidden]{display:none!important}.sp-notes{white-space:pre-wrap;color:#526473;font-size:12px;line-height:1.7}.sp-review{display:grid;gap:14px;margin-top:18px}.sp-check{display:flex;gap:8px;align-items:start;font-size:12px;color:#526473;line-height:1.7}.sp-check input{margin-top:3px;accent-color:#1769d1}.sp-dialog .sc-footer{position:sticky;bottom:-22px;background:#fff;padding:14px 0;margin-top:10px;border-top:1px solid #edf0f4}.sp-status{display:inline-block;padding:5px 9px;border-radius:5px;background:#fff5df;color:#956116;font-size:11px;font-weight:700}.sp-status.closed{background:#edf8ef;color:#166534}.sp-status.cancelled{background:#f0f3f6;color:#667885}.sp-dialog :is(input,button,select,textarea):focus-visible{outline:2px solid #a7c9f4;outline-offset:2px}@media(max-width:650px){.sp-dialog{padding:15px}.sp-row{grid-template-columns:1fr}.sp-dialog .sc-field input,.sp-dialog .sc-field select,.sp-dialog .sc-field textarea,.sp-count-input,.sp-count-search{font-size:16px}.sp-dialog .sc-footer{bottom:-15px;flex-wrap:wrap}.sc-tabs{flex-wrap:wrap}}
.sp-count-sheet{scroll-margin-top:20px}.sp-count-tools{display:flex;justify-content:space-between;align-items:end;gap:16px;flex-wrap:wrap;margin:18px 0}.sp-count-tools .sc-field{flex:1;max-width:430px}.sp-count-tools .sp-count-search{width:100%}.sp-count-sheet .sp-count-input{width:145px;text-align:right;background:#f8fbff}.sp-count-sheet .sp-count-input:focus{background:#fff;border-color:#1769d1}.sp-count-sheet tfoot td{background:#f7f9fb;padding:15px 12px;border-top:2px solid #e2e8ee}.sp-save-bar{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;background:#fff;padding:14px 0;margin-top:12px}.sp-shifts>summary{cursor:pointer;font-size:14px;font-weight:700}.sp-shifts[open]>summary{margin-bottom:12px}.sp-count-sheet button:disabled{opacity:.55;cursor:not-allowed}@media(max-width:650px){.sp-count-tools .sc-field{max-width:none;flex-basis:100%}.sp-save-bar .sc-actions{width:100%}.sp-save-bar .sc-button{flex:1}}
